#!/usr/bin/env python3
"""Minimal classic-TIFF IFD tag dumper (little/big endian, strips/tiles)."""
import struct
import sys


TYPE_SIZE = {1:1, 2:1, 3:2, 4:4, 5:8, 6:1, 7:1, 8:2, 9:4, 10:8, 11:4, 12:8}


def dump(path):
    data = open(path, 'rb').read()
    bo = data[0:2]
    if bo == b'II':
        endian = '<'
    elif bo == b'MM':
        endian = '>'
    else:
        print("bad byte order"); return
    magic, ifd_off = struct.unpack(endian + 'HI', data[2:8])
    print(f"== {path}")
    print(f"   endian={bo.decode()} magic={magic} ifd_offset={ifd_off} filesize={len(data)}")
    ifd = ifd_off
    n = 0
    while ifd:
        (count,) = struct.unpack(endian + 'H', data[ifd:ifd+2])
        print(f"   IFD @ {ifd}: {count} entries")
        entries = []
        for i in range(count):
            eoff = ifd + 2 + i*12
            tag, typ, cnt = struct.unpack(endian + 'HHI', data[eoff:eoff+8])
            val = data[eoff+8:eoff+12]
            tsize = TYPE_SIZE.get(typ, 1) * cnt
            if tsize <= 4:
                raw = val
            else:
                (off,) = struct.unpack(endian + 'I', val)
                raw = data[off:off+tsize]
            entries.append((tag, typ, cnt, raw, tsize))
        for tag, typ, cnt, raw, tsize in sorted(entries):
            extra = ''
            if typ == 3 and cnt > 0:
                fmt = endian + ('H'*cnt)
                vals = struct.unpack(fmt, raw)
                extra = ' vals=' + ','.join(str(v) for v in vals)
            elif typ in (5, 10) and cnt > 0:
                vals = []
                for j in range(cnt):
                    num, den = struct.unpack(endian + ('iI' if typ == 10 else 'II'), raw[j*8:j*8+8])
                    vals.append(f"{num}/{den}")
                extra = ' vals=' + ','.join(vals)
            elif typ == 4 and cnt > 0:
                vals = struct.unpack(endian + 'I'*cnt, raw)
                extra = ' vals=' + ','.join(str(v) for v in vals)
            elif typ == 1 and cnt > 0:
                extra = ' vals=' + ','.join(str(b) for b in raw)
            print(f"     tag={tag} (0x{tag:04X}) type={typ} count={cnt} size={tsize}{extra}")
        (nxt,) = struct.unpack(endian + 'I', data[ifd+2+count*12:ifd+6+count*12])
        ifd = nxt
        n += 1
        if n > 10:
            break


for p in sys.argv[1:]:
    dump(p)

